  "mainEntity": [
    {
      "@type": "Question",
      "name": "Does our brokerage's data ever leave our environment?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Deepvine is deployed inside your brokerage's own infrastructure, and your client records, transaction files, contracts, and prompts stay there. The system connects to the tools you already use and reads your data in place; nothing is copied to a shared cloud, and your inputs are never used to train an outside model."
      }
    },
    {
      "@type": "Question",
      "name": "Is it a problem for agents to paste client details into consumer AI tools?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It can be. Putting a client's financial situation, motivations, or contract terms into a free consumer AI tool can send confidential information to a third party and undercut your fiduciary duty of confidentiality. A private deployment lets your team get AI answers without that information ever reaching an outside vendor."
      }
    },
    {
      "@type": "Question",
      "name": "Can it connect to our CRM, transaction management, and email?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Deepvine is built to connect to the systems a brokerage already runs — your CRM, transaction management platform, document storage, email, and Slack — and to read that history so answers are grounded in your own deals and files rather than the open internet."
      }
    },
    {
      "@type": "Question",
      "name": "What happens to the knowledge base if we end the engagement?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You keep your data and the knowledge base built on it, because both live inside your own environment. There is no vendor lock-in on your institutional memory; the intelligence your brokerage accumulated stays with your brokerage."
      }
    },
    {
      "@type": "Question",
      "name": "Is this only for large brokerages, or do teams benefit too?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Teams benefit as much as large brokerages. When a productive agent leaves, the relationships, deal history, and hard-won local knowledge often walk out with them. A private knowledge system captures that institutional memory so it compounds for the whole team instead of resetting."
      }
    },
    {
      "@type": "Question",
      "name": "What does it cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Pricing depends on the size of your brokerage or team, the systems being connected, and the depth of historical backfill, so we scope it during the demo rather than list a single number. The engagement is structured as an ongoing managed service that includes deployment, maintenance, and updates."
      }
    }
  ]
}

